package sqlquery

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	"sync"
	"testing"
)

type originalSQLCall struct {
	Operation string          `json:"operation"`
	SQL       string          `json:"sql"`
	Result    json.RawMessage `json:"result"`
	Error     *struct {
		Name    string `json:"name"`
		Message string `json:"message"`
	} `json:"error"`
}

// TestUpstreamSQLQuery replays every call from the complete unchanged source
// file, including the actual eight SQL strings generated by its Drizzle schema.
// The capture and pristine oracle retain the source assertions separately.
func TestUpstreamSQLQuery(t *testing.T) {
	raw, err := os.ReadFile("../testdata/sql/captured-original-sql.json")
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Cases []struct {
			ID           string            `json:"id"`
			Title        string            `json:"title"`
			SourceSHA256 string            `json:"source_sha256"`
			Assertions   []json.RawMessage `json:"assertions"`
			Calls        []originalSQLCall `json:"calls"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	if len(fixture.Cases) != 14 {
		t.Fatalf("Original declarations: got %d, want 14", len(fixture.Cases))
	}
	validator := NewValidator()
	for _, original := range fixture.Cases {
		t.Run(original.Title, func(t *testing.T) {
			if len(original.Calls) == 0 {
				t.Fatal("Missing original operations")
			}
			if original.ID == "1bf6f8198d48a808c3af" || original.ID == "3526ec1ef69fdec4b80c" {
				// Preserve the source's deliberate 40-bit SHA prefix collisions.
				first := sha256.Sum256([]byte(original.Calls[0].SQL))
				second := sha256.Sum256([]byte(original.Calls[1].SQL))
				firstHash, secondHash := hex.EncodeToString(first[:]), hex.EncodeToString(second[:])
				if firstHash[:10] != secondHash[:10] || firstHash == secondHash {
					t.Fatalf("Original cache collision assertions: %s, %s", firstHash, secondHash)
				}
			}
			check := func(call originalSQLCall) error {
				var value any
				var err error
				switch call.Operation {
				case "validateAllowableSQLQuery":
					err = validator.Validate(call.SQL)
					value = map[string]any{"$undefined": true}
				case "getSQLQueryRelations":
					var relations *RelationSet
					relations, err = validator.Relations(call.SQL)
					if err == nil {
						value = map[string]any{"$set": relations.Values()}
					}
				case "parseSQLQuery":
					value, err = Parse(call.SQL)
				default:
					return fmt.Errorf("Unknown original operation: %s", call.Operation)
				}
				if call.Error != nil {
					if err == nil || err.Error() != call.Error.Message {
						return fmt.Errorf("%s: got error %v, source %s: %s", call.Operation, err, call.Error.Name, call.Error.Message)
					}
					return nil
				}
				if err != nil {
					return fmt.Errorf("%s: %w", call.Operation, err)
				}
				actual, err := json.Marshal(value)
				if err != nil {
					return err
				}
				var got, want any
				if err = json.Unmarshal(actual, &got); err != nil {
					return err
				}
				if err = json.Unmarshal(call.Result, &want); err != nil {
					return err
				}
				if !reflect.DeepEqual(got, want) {
					return fmt.Errorf("%s: native=%s source=%s", call.Operation, actual, call.Result)
				}
				return nil
			}
			if original.ID == "881b4ac5b3e7c5f0e721" {
				// The source starts all three validations before awaiting them.
				gate := make(chan struct{})
				errors := make(chan error, len(original.Calls))
				var workers sync.WaitGroup
				for _, call := range original.Calls {
					workers.Add(1)
					go func() {
						defer workers.Done()
						<-gate
						errors <- check(call)
					}()
				}
				close(gate)
				workers.Wait()
				close(errors)
				for err := range errors {
					if err != nil {
						t.Error(err)
					}
				}
			} else {
				for _, call := range original.Calls {
					if err := check(call); err != nil {
						t.Fatal(err)
					}
				}
			}
		})
	}
}
